import random
A='GUCGAACCUGAAGUAGAUAUUAGAGCAUAUAAGAAGAAAGAGCAAAAACGGGCGCGUAUCCCGUGUUUGAC'
B='GCUCCGCGUAGGUGACCAUUGACCUCCCUCAUAACUCUCCCGGGUCCAGACUUGACUGAAAGGUUGCGGGGU'
C='UACUAAUCUCACGUUUCAUGUCGUGGAGAAUAAAGCACAUUCUCAAGAAGGUUACACGCGGACUUAUUGGUA'
# reverse-complement-flavored variants: reverse each domain to get a different solution of same structure
def rc(s):
    comp={'A':'U','U':'A','G':'C','C':'G'}
    return ''.join(comp[c] for c in reversed(s))
A2=rc(A); B2=rc(B); C2=rc(C)
# also try complement-only (not reversed) - keeps pairing
def comp_only(s):
    comp={'A':'U','U':'A','G':'C','C':'G'}
    return ''.join(comp[c] for c in s)
A3=comp_only(A); B3=comp_only(B); C3=comp_only(C)
domains_A=[A,A2,A3]
domains_B=[B,B2,B3]
domains_C=[C,C2,C3]
linkers=['AAAA','AAAU','AAUU','AUUU','UUUU','AAAC','GAAA','UUCG']
random.seed(7)
seqs=[]
# combos
for a in domains_A:
    for b in domains_B:
        for c in domains_C:
            for _ in range(8):
                L=[random.choice(linkers) for _ in range(5)]
                seqs.append(a+L[0]+b+L[1]+c+L[2]+c+L[3]+c+L[4])
print(len(seqs))
with open('/tmp/mix.txt','w') as f:
    for s in seqs: f.write(s+'\n')
